    "Image Error Handling": {
      "react": "import { useState } from \"react\";\nimport { Avatar } from \"@chumlab/ui/avatar\";\n\nexport default function AvatarExample() {\n  const [imageError, setImageError] = useState(false);\n  return (\n    <Avatar\n      src={imageError ? \"\" : \"data:image/gif;base64,invalid\"}\n      name=\"John Doe\"\n      autoColor\n      colors={\n        {\n          backgrounds: [\n            \"#e0e7ff\",\n            \"#dbeafe\",\n            \"#d1fae5\",\n            \"#fef9c3\",\n            \"#fce7f3\",\n            \"#ede9fe\",\n            \"#cffafe\",\n            \"#fef2f2\"\n          ],\n          text: [\n            \"#4f46e5\",\n            \"#1d4ed8\",\n            \"#047857\",\n            \"#854d0e\",\n            \"#be185d\",\n            \"#7c3aed\",\n            \"#0e7490\",\n            \"#ef4444\"\n          ]\n        }\n      }\n      onError={() => setImageError(true)}\n      imageConfig={{ loading: \"eager\" }}\n    />\n  );\n}\n",
      "next": "\"use client\";\n\nimport { useState } from \"react\";\nimport { Avatar } from \"@chumlab/ui/avatar\";\n\nexport default function AvatarExample() {\n  const [imageError, setImageError] = useState(false);\n  return (\n    <Avatar\n      src={imageError ? \"\" : \"data:image/gif;base64,invalid\"}\n      name=\"John Doe\"\n      autoColor\n      colors={\n        {\n          backgrounds: [\n            \"#e0e7ff\",\n            \"#dbeafe\",\n            \"#d1fae5\",\n            \"#fef9c3\",\n            \"#fce7f3\",\n            \"#ede9fe\",\n            \"#cffafe\",\n            \"#fef2f2\"\n          ],\n          text: [\n            \"#4f46e5\",\n            \"#1d4ed8\",\n            \"#047857\",\n            \"#854d0e\",\n            \"#be185d\",\n            \"#7c3aed\",\n            \"#0e7490\",\n            \"#ef4444\"\n          ]\n        }\n      }\n      onError={() => setImageError(true)}\n      imageConfig={{ loading: \"eager\" }}\n    />\n  );\n}\n",
      "needsClientBoundary": true
    },
