    "Controlled Mode": {
      "react": "import { useState } from \"react\";\nimport { Button } from \"@chumlab/ui/button\";\nimport { RadioButton, RadioGroup } from \"@chumlab/ui/radio-button\";\n\nexport default function RadioButtonExample() {\n  const [controlled, setControlled] = useState(\"option-a\");\n  return (\n    <>\n      <div className=\"w-full mb-3 p-3 rounded-cl-md flex items-center gap-3 bg-cl-bg-elevated\">\n        <span className=\"text-xs font-medium text-cl-text-secondary\">Selected:</span>\n        <span className=\"text-sm font-mono text-cl-text-secondary\">\n          {controlled}\n        </span>\n        <Button\n          size=\"sm\"\n          className=\"ml-auto rounded-cl-md bg-cl-bg-elevated text-cl-text border border-cl-border hover:border-cl-border-input-hover hover:bg-cl-bg-hover\"\n          onClick={\n            () =>\n            setControlled((prev) =>\n              prev === \"option-a\"\n                ? \"option-b\"\n                : prev === \"option-b\"\n                  ? \"option-c\"\n                  : \"option-a\",\n            )\n          }\n        >\n          Cycle Externally\n        </Button>\n      </div>\n      <RadioGroup\n        name=\"controlled\"\n        value={controlled}\n        onValueChange={setControlled}\n        size=\"md\"\n        classes={\n          {\n            root: \"\",\n            label: \"text-sm font-medium text-cl-text\",\n            description: \"text-xs text-cl-text-secondary\"\n          }\n        }\n      >\n        <RadioButton\n          value=\"option-a\"\n          label=\"Option A\"\n          classes={\n            {\n              root: \"flex items-center gap-2\",\n              label: \"text-sm font-medium text-cl-text\",\n              description: \"text-xs text-cl-text-secondary\"\n            }\n          }\n        />\n        <RadioButton\n          value=\"option-b\"\n          label=\"Option B\"\n          classes={\n            {\n              root: \"flex items-center gap-2\",\n              label: \"text-sm font-medium text-cl-text\",\n              description: \"text-xs text-cl-text-secondary\"\n            }\n          }\n        />\n        <RadioButton\n          value=\"option-c\"\n          label=\"Option C\"\n          classes={\n            {\n              root: \"flex items-center gap-2\",\n              label: \"text-sm font-medium text-cl-text\",\n              description: \"text-xs text-cl-text-secondary\"\n            }\n          }\n        />\n      </RadioGroup>\n    </>\n  );\n}\n",
      "next": "\"use client\";\n\nimport { useState } from \"react\";\nimport { Button } from \"@chumlab/ui/button\";\nimport { RadioButton, RadioGroup } from \"@chumlab/ui/radio-button\";\n\nexport default function RadioButtonExample() {\n  const [controlled, setControlled] = useState(\"option-a\");\n  return (\n    <>\n      <div className=\"w-full mb-3 p-3 rounded-cl-md flex items-center gap-3 bg-cl-bg-elevated\">\n        <span className=\"text-xs font-medium text-cl-text-secondary\">Selected:</span>\n        <span className=\"text-sm font-mono text-cl-text-secondary\">\n          {controlled}\n        </span>\n        <Button\n          size=\"sm\"\n          className=\"ml-auto rounded-cl-md bg-cl-bg-elevated text-cl-text border border-cl-border hover:border-cl-border-input-hover hover:bg-cl-bg-hover\"\n          onClick={\n            () =>\n            setControlled((prev) =>\n              prev === \"option-a\"\n                ? \"option-b\"\n                : prev === \"option-b\"\n                  ? \"option-c\"\n                  : \"option-a\",\n            )\n          }\n        >\n          Cycle Externally\n        </Button>\n      </div>\n      <RadioGroup\n        name=\"controlled\"\n        value={controlled}\n        onValueChange={setControlled}\n        size=\"md\"\n        classes={\n          {\n            root: \"\",\n            label: \"text-sm font-medium text-cl-text\",\n            description: \"text-xs text-cl-text-secondary\"\n          }\n        }\n      >\n        <RadioButton\n          value=\"option-a\"\n          label=\"Option A\"\n          classes={\n            {\n              root: \"flex items-center gap-2\",\n              label: \"text-sm font-medium text-cl-text\",\n              description: \"text-xs text-cl-text-secondary\"\n            }\n          }\n        />\n        <RadioButton\n          value=\"option-b\"\n          label=\"Option B\"\n          classes={\n            {\n              root: \"flex items-center gap-2\",\n              label: \"text-sm font-medium text-cl-text\",\n              description: \"text-xs text-cl-text-secondary\"\n            }\n          }\n        />\n        <RadioButton\n          value=\"option-c\"\n          label=\"Option C\"\n          classes={\n            {\n              root: \"flex items-center gap-2\",\n              label: \"text-sm font-medium text-cl-text\",\n              description: \"text-xs text-cl-text-secondary\"\n            }\n          }\n        />\n      </RadioGroup>\n    </>\n  );\n}\n",
      "needsClientBoundary": true
    }
