      "react": "import { Button } from \"@chumlab/ui/button\";\nimport { ToastProvider, useToast } from \"@chumlab/ui/toast\";\n\nconst LocalProviderTrigger = ({\n  className,\n  label,\n  message,\n  duration,\n}: {\n  className: string;\n  label: string;\n  message: string;\n  duration?: number;\n}) => {\n  const { info } = useToast();\n  return (\n    <button className={className} onClick={() => info(message, { duration })}>\n      {label}\n    </button>\n  );\n};\n\nconst LocalProviderDemo = ({\n  buttonClassName,\n  label,\n  message,\n  duration,\n  ...providerProps\n}: Omit<React.ComponentProps<typeof ToastProvider>, \"children\"> & {\n  buttonClassName: string;\n  label: string;\n  message: string;\n  duration?: number;\n}) => (\n  <ToastProvider {...providerProps}>\n    <LocalProviderTrigger className={buttonClassName} label={label} message={message} duration={duration} />\n  </ToastProvider>\n);\n\nfunction ToastTrigger() {\n  const toast = useToast();\n  return (\n    <>\n      <Button\n        className=\"px-3 py-1.5 text-xs font-medium rounded-cl-md transition-colors cursor-pointer bg-cl-accent text-cl-on-accent hover:bg-cl-accent/90 dark:bg-cl-accent dark:text-cl-on-accent dark:hover:bg-cl-accent/90\"\n        onClick={\n          () =>\n          toast.info(\"Press Escape to dismiss\", {\n            duration: Infinity,\n            description:\n              \"This toast can be dismissed with the Escape key\"\n          })\n        }\n      >\n        With Escape Dismissal\n      </Button>\n      <LocalProviderDemo\n        closeOnEscape={false}\n        containerAriaLabel=\"Escape disabled example\"\n        buttonClassName=\"px-3 py-1.5 text-xs font-medium rounded-cl-md transition-colors cursor-pointer bg-cl-bg-panel border border-cl-border dark:border-cl-text-tertiary text-cl-text hover:bg-cl-bg-hover\"\n        label=\"Without Escape Dismissal\"\n        message=\"Escape leaves this one; use its close button\"\n        duration={Infinity}\n      />\n    </>\n  );\n}\n\nexport default function ToastExample() {\n  return (\n    <ToastProvider>\n      <ToastTrigger />\n    </ToastProvider>\n  );\n}\n",
